#include "CaptureStrategy.h"
#include "../CaptureGeometry.h"

#include <QClipboard>
#include <QDebug>
#include <QFileDialog>
#include <QGuiApplication>
#include <QStandardPaths>

namespace Capture {

// This file provides the implementation for the CaptureStrategy base class
// The signals are automatically generated by Qt's MOC system

void CaptureStrategy::copyAreaToClipboard(const QPixmap &shot, const QRect &virtualGeometry,
                                          const QRect &area)
{
    const QPixmap cropped = cropVirtualArea(shot, virtualGeometry, area);
    if (cropped.isNull())
        return;

    QGuiApplication::clipboard()->setPixmap(cropped);
    qDebug() << "Selection copied to clipboard:" << cropped.size();
}

void CaptureStrategy::saveAreaToFile(const QPixmap &shot, const QRect &virtualGeometry,
                                     const QRect &area)
{
    const QPixmap cropped = cropVirtualArea(shot, virtualGeometry, area);
    if (cropped.isNull())
        return;

    // The overlay is already torn down, so this dialog isn't hidden behind it.
    const QString fileName = QFileDialog::getSaveFileName(
        nullptr, "Save Screenshot",
        QStandardPaths::writableLocation(QStandardPaths::PicturesLocation) + "/screenshot.png",
        "Image Files (*.png *.jpg *.bmp)");
    if (!fileName.isEmpty())
        cropped.save(fileName);
}

} // namespace Capture
